const { chromium } = require('playwright');
const { AxeBuilder } = require('@axe-core/playwright');
const BASE = 'http://127.0.0.1:8765/';
const assert = (c, m) => { if (!c) throw new Error('FAIL: ' + m); console.log('ok -', m); };
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => m.type() === 'error' && errors.push(m.text()));

  async function axe(name) {
    const r = await new AxeBuilder({ page }).withTags(['wcag2a','wcag2aa','wcag21aa','wcag22aa','best-practice']).analyze();
    r.violations.forEach(v => console.log(`  axe[${name}] ${v.id}: ${v.help} (${v.nodes.length}) ${v.nodes[0].target}`));
    assert(r.violations.length === 0, `axe clean: ${name}`);
  }

  for (const p of ['index.html','catalog.html','register.html','profile.html']) {
    await page.goto(BASE + p); await axe(p);
    await page.screenshot({ path: `/tmp/shots/${p}.png`, fullPage: true });
  }

  // Home search -> catalog
  await page.goto(BASE);
  await page.fill('#hero-q', 'calculus'); await page.click('.hero-search button');
  await page.waitForURL(/catalog/);
  assert((await page.textContent('#results-count')).includes('Showing 1 of 16'), 'home search carries to catalog');

  // Filters
  await page.click('button[type=reset]'); await page.waitForTimeout(50);
  await page.selectOption('#dept', 'CS');
  assert((await page.locator('#course-results > li').count()) === 3, 'dept filter CS = 3');
  await page.check('#open');
  assert((await page.locator('#course-results > li').count()) === 2, 'open-only hides full CS240');
  await page.click('button[type=reset]'); await page.waitForTimeout(50);
  await page.selectOption('#day', 'Fri'); await page.selectOption('#credits', '4');
  assert((await page.locator('#course-results > li').count()) === 4, 'Fri + 4 credits = 4');
  await page.click('button[type=reset]'); await page.waitForTimeout(50);
  await page.fill('#q', 'zzzz'); await page.waitForTimeout(400);
  assert(await page.isVisible('.empty-state'), 'empty state'); await axe('catalog empty');
  await page.click('button[type=reset]'); await page.waitForTimeout(50);

  // Add courses to cart (MATH230 + PSY101 conflict)
  for (const id of ['CS101','MATH230','PSY101']) await page.click(`[data-action=toggle-cart][data-id=${id}]`);
  assert(await page.evaluate(() => document.activeElement.dataset.id === 'PSY101'), 'focus stays on toggled button');
  assert((await page.textContent('.nav-links [data-cart-count] [aria-hidden]')) === '3', 'badge = 3');
  await page.waitForTimeout(100);
  assert((await page.textContent('#announcer')).includes('PSY 101 added'), 'live announcement');

  // Register: errors
  await page.goto(BASE + 'register.html');
  assert((await page.locator('input[name=courses]:checked').count()) === 3, 'cart preselected');
  await page.fill('#studentId', '12');
  await page.click('button[type=submit]');
  assert(await page.isVisible('#error-summary'), 'error summary shown');
  assert(await page.evaluate(() => document.activeElement.id === 'error-summary'), 'error summary focused');
  const errs = await page.locator('#error-summary li').allTextContents(); console.log('   ', errs);
  assert(errs.some(e => e.includes('same time')) && errs.some(e => e.includes('8 digits')), 'conflict + id errors');
  assert(await page.getAttribute('#studentId', 'aria-invalid') === 'true', 'aria-invalid set');
  await axe('register errors');
  await page.click('#error-summary a[href="#studentId"]');
  assert(await page.evaluate(() => document.activeElement.id === 'studentId'), 'summary link focuses field');

  // Fix and submit
  await page.fill('#studentId', '20251234');
  await page.uncheck('input[value=PSY101]'); await page.check('#agree');
  await page.click('button[type=submit]');
  assert(await page.isVisible('#confirm-dialog'), 'confirmation modal open');
  assert(await page.evaluate(() => document.activeElement.matches('[data-dialog-confirm]')), 'focus in modal');
  await axe('register modal');
  await page.screenshot({ path: '/tmp/shots/modal.png' });
  await page.keyboard.press('Escape');
  assert(!(await page.isVisible('#confirm-dialog')), 'Esc closes modal');
  assert(await page.evaluate(() => document.activeElement.type === 'submit'), 'focus returned to submit');
  await page.click('button[type=submit]'); await page.click('[data-dialog-confirm]');
  assert(await page.isVisible('#registration-success'), 'success message');
  assert(await page.evaluate(() => document.activeElement.id === 'registration-success'), 'success focused');
  assert((await page.locator('input[name=courses]:disabled').count()) >= 4, 'registered now disabled');

  // Profile table + drop
  await page.goto(BASE + 'profile.html');
  assert((await page.locator('#registered-body tr').count()) === 2, 'table has 2 rows');
  assert((await page.textContent('#total-credits')) === '7', 'total credits 7');
  await axe('profile with data');
  await page.screenshot({ path: '/tmp/shots/profile-filled.png', fullPage: true });
  await page.click('[data-drop=CS101]');
  assert(await page.evaluate(() => document.activeElement.matches('[data-dialog-cancel]')), 'drop modal focuses Cancel');
  await page.click('[data-dialog-confirm]');
  assert((await page.locator('#registered-body tr').count()) === 1, 'dropped');
  assert(await page.evaluate(() => document.activeElement.id === 'registered-heading'), 'focus to heading after drop');

  // Mobile nav
  const m = await browser.newPage({ viewport: { width: 375, height: 800 } });
  await m.goto(BASE + 'catalog.html');
  assert(!(await m.isVisible('#nav-menu')), 'mobile menu collapsed');
  await m.click('.nav-toggle');
  assert(await m.isVisible('#nav-menu') && await m.getAttribute('.nav-toggle','aria-expanded') === 'true', 'mobile menu opens');
  await m.screenshot({ path: '/tmp/shots/mobile-catalog.png', fullPage: false });
  await m.keyboard.press('Escape');
  assert(!(await m.isVisible('#nav-menu')), 'Esc closes menu');
  const overflow = await m.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
  assert(!overflow, 'no horizontal overflow at 375px');
  for (const p of ['index.html','register.html','profile.html']) {
    await m.goto(BASE + p);
    assert(!(await m.evaluate(() => document.documentElement.scrollWidth > window.innerWidth)), `no overflow ${p} @375`);
    await m.screenshot({ path: `/tmp/shots/mobile-${p}.png`, fullPage: true });
  }

  assert(errors.length === 0, 'no console errors ' + errors.join('; '));
  await browser.close();
})().catch(e => { console.error(e.message); process.exit(1); });
EOF
